class Solution:
    def findCriticalAndPseudoCriticalEdges(self, n: int, edges: list[list[int]]) -> list[list[int]]:
        indexed_edges = sorted((w, a, b, i) for i, (a, b, w) in enumerate(edges))

        def connected(graph, start, target):
            visited = {start}
            frontier = [start]

            while frontier:
                next_frontier = []
                for node in frontier:
                    if node == target:
                        return True
                    for neighbor in graph[node]:
                        if neighbor in visited:
                            continue
                        visited.add(neighbor)
                        next_frontier.append(neighbor)
                frontier = next_frontier
            return False

        def mst_weight(include=None, exclude=None):
            graph = [[] for _ in range(n)]
            weight = 0
            count = 0
            if include is not None:
                cost, a, b, _ = include
                graph[a].append(b)
                graph[b].append(a)
                weight += cost
                count += 1

            for cost, a, b, index in indexed_edges:
                if index == exclude:
                    continue
                if connected(graph, a, b):
                    continue
                graph[a].append(b)
                graph[b].append(a)
                weight += cost
                count += 1

            return weight if count == n - 1 else float('inf')

        base = mst_weight()
        critical = []
        pseudo = []
        for edge in indexed_edges:
            index = edge[3]
            if mst_weight(exclude=index) > base:
                critical.append(index)
            elif mst_weight(include=edge) == base:
                pseudo.append(index)
        return [critical, pseudo]

